import * as t from '@babel/types';

/** Name shapes generated by common obfuscators that are safe to rename. */
export const JUNK_NAME_RE = /^(_0x[0-9a-fA-F]{2,}|td_[A-Za-z0-9]{1,5})$/;

/**
 * Extract the value of a literal-ish node, treating unshadowed
 * `undefined` / `NaN` / `Infinity` as constants.
 */
export function literalValue(path) {
  return literalValueOf(path, path.node);
}

/**
 * Same as `literalValue` but takes the child node directly instead of a
 * child path. Creating child NodePaths mid-traversal (path.get on a
 * mutated tree) can force Babel to re-crawl scopes and re-enter the
 * traversal :  see the stack-overflow fix in fold-constants.
 */
export function literalValueOf(parentPath, node) {
  if (t.isStringLiteral(node) || t.isNumericLiteral(node) || t.isBooleanLiteral(node)) {
    return { ok: true, value: node.value };
  }
  if (t.isUnaryExpression(node) && node.operator === '-' && t.isNumericLiteral(node.argument)) {
    return { ok: true, value: -node.argument.value };
  }
  if (t.isUnaryExpression(node) && node.operator === '+' && t.isNumericLiteral(node.argument)) {
    return { ok: true, value: +node.argument.value };
  }
  if (t.isNullLiteral(node)) return { ok: true, value: null };
  if (t.isIdentifier(node) && !hasLocalBinding(parentPath, node.name)) {
    if (node.name === 'undefined') return { ok: true, value: undefined };
    if (node.name === 'NaN') return { ok: true, value: NaN };
    if (node.name === 'Infinity') return { ok: true, value: Infinity };
  }
  return { ok: false };
}

/** Build an AST node holding a folded constant, or null if unrepresentable. */
export function literalNode(value) {
  if (value === undefined) return t.identifier('undefined');
  if (typeof value === 'number' && Number.isNaN(value)) return t.identifier('NaN');
  if (value === Infinity) return t.identifier('Infinity');
  if (value === -Infinity) return t.unaryExpression('-', t.identifier('Infinity'));
  if (typeof value === 'number') {
    if (Object.is(value, -0)) return t.unaryExpression('-', t.numericLiteral(0));
    return value < 0
      ? t.unaryExpression('-', t.numericLiteral(-value))
      : t.numericLiteral(value);
  }
  if (typeof value === 'bigint') return t.bigIntLiteral(value.toString());
  if (typeof value === 'string') return t.stringLiteral(value);
  if (typeof value === 'boolean') return t.booleanLiteral(value);
  if (value === null) return t.nullLiteral();
  return null;
}

/**
 * True when a scope chain declares `name` as a real binding. Unlike
 * `scope.hasBinding`, this ignores host globals :  `Number` and `unescape`
 * are globals, not bindings, so passes can still fold calls to them.
 */
export function hasLocalBinding(path, name) {
  let scope = path.scope;
  while (scope) {
    if (Object.prototype.hasOwnProperty.call(scope.bindings, name)) return true;
    scope = scope.parent;
  }
  return false;
}

/**
 * True when the node is an array literal of at least `min` string literals : 
 * the storage shape of every string-concealing obfuscator.
 */
export function isAllStringArray(node, min = 3) {
  return (
    t.isArrayExpression(node) &&
    node.elements.length >= min &&
    node.elements.every((element) => t.isStringLiteral(element))
  );
}

/**
 * Evaluate a pure literal expression (numbers, strings, unary/binary chains
 * over them) to its primitive value. Returns undefined when the node isn't
 * statically computable :  callers treat that as "leave it alone".
 */
export function evalLiteralExpr(node, depth = 0) {
  if (depth > 64 || node == null) return undefined;
  if (t.isNumericLiteral(node) || t.isStringLiteral(node) || t.isBooleanLiteral(node)) {
    return node.value;
  }
  if (t.isNullLiteral(node)) return null;
  if (t.isIdentifier(node)) {
    if (node.name === 'undefined') return undefined;
    if (node.name === 'NaN') return NaN;
    if (node.name === 'Infinity') return Infinity;
  }
  if (t.isUnaryExpression(node)) {
    if (node.operator === 'void') return undefined;
    const value = evalLiteralExpr(node.argument, depth + 1);
    if (value === undefined) return undefined;
    switch (node.operator) {
      case '-': return -value;
      case '+': return +value;
      case '~': return ~value;
      case '!': return !value;
      default: return undefined;
    }
  }
  if (t.isBinaryExpression(node)) {
    const left = evalLiteralExpr(node.left, depth + 1);
    const right = evalLiteralExpr(node.right, depth + 1);
    if (left === undefined || right === undefined) return undefined;
    switch (node.operator) {
      case '+': return left + right;
      case '-': return left - right;
      case '*': return left * right;
      case '/': return left / right;
      case '%': return left % right;
      case '**': return left ** right;
      case '<<': return left << right;
      case '>>': return left >> right;
      case '>>>': return left >>> right;
      case '&': return left & right;
      case '|': return left | right;
      case '^': return left ^ right;
      default: return undefined;
    }
  }
  return undefined;
}

/**
 * Flatten `a.b.c` or `a["b"]["c"]` member chains into ['a', 'b', 'c'].
 * Returns null when any link is dynamic non-string or unknown.
 */
export function memberPathParts(node) {
  const parts = [];
  let current = node;
  while (t.isMemberExpression(current)) {
    if (!current.computed && t.isIdentifier(current.property)) {
      parts.unshift(current.property.name);
    } else if (current.computed && t.isStringLiteral(current.property)) {
      parts.unshift(current.property.value);
    } else {
      return null;
    }
    current = current.object;
  }
  if (t.isIdentifier(current)) {
    parts.unshift(current.name);
    return parts;
  }
  return null;
}
